#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n,m;scanf("%d %d",&n,&m);vector<int>d(n+1,0);
for(int i=0;i<m;++i){int u,v;scanf("%d %d",&u,&v);
if(u==v)d[u]+=2;else{++d[u];++d[v];}}
for(int i=1;i<=n;++i){if(i>1)printf(" ");printf("%d",d[i]);}
printf("\n");return 0;}

